#if DEBUG
import Foundation

// The demo dataset: real, current chart albums with their real cover art, played by a made-up listener, for
// screenshots (`OPENMUSIC_MOCK=demo` on the Mac, `-OpenMusicMock demo` on iOS; `scripts/demo-shots.sh`).
// Debug builds only. Titles and track lengths come from DemoCatalogData.swift (generated by
// scripts/demo-catalog.py); cover art is downloaded at run time (scripts/demo-art.sh) and read through
// `MockArtwork.demoDirectory`, falling back to procedural art when it's missing. Lyrics are the mock layer's own
// placeholder lines, never a song's real words.

struct DemoSong: Sendable {
    let title: String
    let seconds: Int
    let explicit: Bool
    let artists: [String]?

    init(_ title: String, _ seconds: Int, explicit: Bool = false, artists: [String]? = nil) {
        self.title = title
        self.seconds = seconds
        self.explicit = explicit
        self.artists = artists
    }
}

struct DemoAlbum: Sendable {
    let key: String
    let service: ProviderID
    let title: String
    let artists: [String]
    let released: String
    let kind: AlbumKind
    let genre: String
    let copyright: String
    let tracks: [DemoSong]
}

enum DemoCatalogData {}

/// The made-up account every demo service is signed in as. Not a real person.
public enum DemoAccount {
    public static let name = "Riley Calder"
    static let initials = "RC"
}

/// What the demo plays: an album, the song to start at, and where in the song.
public struct DemoNowPlaying: Sendable {
    public let album: Album
    public let tracks: [Track]
    public let index: Int
    public let position: TimeInterval
}

extension MockCatalog {
    init(demo provider: ProviderID) {
        self.provider = provider
        dataset = .demo
        let short = provider.short
        let source = DemoCatalogData.albums.filter { $0.service == provider }

        func artistID(_ name: String) -> String { "\(short)-ar-\(Self.slug(name))" }

        var artistOrder: [String] = []
        var firstCover: [String: String] = [:]
        for album in source {
            for name in album.artists where !artistOrder.contains(name) {
                artistOrder.append(name)
                firstCover[name] = album.key
            }
        }

        for album in source {
            let albumID = "\(short)-\(album.key)"
            let art = MockArtwork.artwork("demo", album.key)
            let refs = album.artists.map { ArtistRef(id: artistID($0), name: $0) }
            let tracks = album.tracks.enumerated().map { i, song in
                Track(
                    providerID: "\(albumID)-t\(i)", provider: provider, title: song.title,
                    artists: (song.artists ?? album.artists).map { ArtistRef(id: artistID($0), name: $0) },
                    album: AlbumRef(id: albumID, title: album.title),
                    duration: TimeInterval(song.seconds), artwork: art, isExplicit: song.explicit, trackNumber: i + 1
                )
            }
            albumTracks[albumID] = tracks
            albums.append(Album(
                providerID: albumID, provider: provider, title: album.title, artists: refs,
                year: Int(album.released.prefix(4)), artwork: art, kind: album.kind, trackCount: tracks.count,
                isExplicit: tracks.contains(where: \.isExplicit),
                extra: ["released": album.released, "genre": album.genre, "copyright": album.copyright]
            ))
        }

        for name in artistOrder {
            let photo = DemoCatalogData.artistPhotos[name] ?? firstCover[name]
            artists.append(Artist(providerID: artistID(name), provider: provider, name: name, artwork: photo.flatMap { MockArtwork.artwork("demo", $0) }))
        }

        // Mixes and the listener's own playlists, each from a fixed, seeded pick of this service's songs.
        let all = allTracks
        var rng = SeededRandom(seed: fnv1a("demo-\(provider.rawValue)"))
        for (i, spec) in Self.playlistSpecs(provider).enumerated() {
            let id = "\(short)-pl\(i)"
            var picked: [Track]
            switch spec.pick {
            case .newest:
                let recent = albums.sorted { ($0.extra["released"] ?? "") > ($1.extra["released"] ?? "") }.prefix(8)
                picked = recent.flatMap { (albumTracks[$0.providerID] ?? []).prefix(3) }
            case .liked:
                picked = all.enumerated().filter { $0.offset % 5 == 0 }.map(\.element)
            case .random(let count):
                picked = Array(all.shuffled(using: &rng).prefix(count))
            }
            let covers = Self.distinctAlbums(picked, count: 4)
            let artwork: Artwork? = switch spec.art {
            case .mosaic: covers.count == 4 ? MockArtwork.artwork("mosaic", covers.joined(separator: "+")) : covers.first.flatMap { MockArtwork.artwork("demo", $0) }
            case .liked: MockArtwork.artwork("liked", provider.rawValue)
            }
            let names = Self.leadArtists(picked, count: 3)
            playlistTracks[id] = picked
            var extra: [String: String] = [:]
            if case .liked = spec.pick { extra[Playlist.likedSongsKey] = "1" }
            playlists.append(Playlist(
                providerID: id, provider: provider, title: spec.title,
                owner: spec.mine ? DemoAccount.name : provider.displayName,
                artwork: artwork, trackCount: picked.count,
                summary: spec.summary ?? (spec.mine || names.isEmpty ? nil : "\(names.joined(separator: ", ")) and more"),
                isEditable: spec.mine,
                extra: extra
            ))
        }
    }

    /// An id-safe form of a name: ASCII letters and digits, dashes between, at most 48.
    static func slug(_ s: String) -> String {
        let folded = s.folding(options: [.diacriticInsensitive, .caseInsensitive], locale: Locale(identifier: "en_US_POSIX"))
        var out = ""
        var dash = false
        for ch in folded.unicodeScalars {
            if ch.isASCII, CharacterSet.alphanumerics.contains(ch) {
                out.unicodeScalars.append(ch)
                dash = false
            } else if !dash, !out.isEmpty {
                out.append("-")
                dash = true
            }
        }
        while out.hasSuffix("-") { out.removeLast() }
        return String(out.prefix(48))
    }

    /// The first `count` different album covers among `tracks` (their artwork keys).
    private static func distinctAlbums(_ tracks: [Track], count: Int) -> [String] {
        var keys: [String] = []
        for t in tracks {
            guard let key = t.artwork?.images.first?.url.lastPathComponent, !keys.contains(key) else { continue }
            keys.append(key)
            if keys.count == count { break }
        }
        return keys
    }

    private static func leadArtists(_ tracks: [Track], count: Int) -> [String] {
        var names: [String] = []
        for t in tracks {
            guard let name = t.artists.first?.name, !names.contains(name) else { continue }
            names.append(name)
            if names.count == count { break }
        }
        return names
    }

    private struct PlaylistSpec {
        enum Pick { case random(Int), newest, liked }
        enum Art { case mosaic, liked }
        let title: String
        var summary: String?
        var mine = false
        var pick: Pick = .random(40)
        var art: Art = .mosaic
    }

    private static func playlistSpecs(_ provider: ProviderID) -> [PlaylistSpec] {
        if provider == .youtubeMusic {
            return [
                PlaylistSpec(title: "Liked Music", summary: "Auto playlist", pick: .liked, art: .liked),
                PlaylistSpec(title: "My Supermix", pick: .random(50)),
                PlaylistSpec(title: "My Mix 1"),
                PlaylistSpec(title: "My Mix 2"),
                PlaylistSpec(title: "Discover Mix", summary: "New music picked for you, refreshed every Wednesday"),
                PlaylistSpec(title: "New Release Mix", pick: .newest),
                PlaylistSpec(title: "late night drive", mine: true, pick: .random(28)),
                PlaylistSpec(title: "gym", mine: true, pick: .random(32)),
                PlaylistSpec(title: "Sunday Reset", mine: true, pick: .random(22)),
            ]
        }
        return [
            PlaylistSpec(title: "Daily Mix 1"),
            PlaylistSpec(title: "Discover Weekly", summary: "Your weekly mixtape of fresh music. Enjoy new music and deep cuts picked for you. Updates every Monday."),
            PlaylistSpec(title: "Release Radar", summary: "Catch all the latest music from artists you follow, plus new singles picked for you.", pick: .newest),
            PlaylistSpec(title: "Daily Mix 2"),
            PlaylistSpec(title: "On Repeat", summary: "Songs you love right now", pick: .random(30)),
            PlaylistSpec(title: "fall 2026", mine: true, pick: .random(34)),
            PlaylistSpec(title: "road trip", mine: true, pick: .random(40)),
        ]
    }
}

// MARK: Shelves

enum DemoShelves {
    /// A song by album key and title (or the start of its title), if this service has it.
    static func track(_ c: MockCatalog, _ albumKey: String, _ title: String) -> Track? {
        let tracks = c.albumTracks["\(c.provider.short)-\(albumKey)"] ?? []
        return tracks.first { $0.title == title } ?? tracks.first { $0.title.lowercased().hasPrefix(title.lowercased()) }
    }

    static func album(_ c: MockCatalog, _ key: String) -> Album? { c.album("\(c.provider.short)-\(key)") }

    /// This service's chart songs, in chart order.
    static func chart(_ c: MockCatalog) -> [Track] {
        let picks: [(String, String)] = c.provider == .youtubeMusic ? [
            ("tate-mcrae-housewife", "Housewife"),
            ("olivia-rodrigo-you-seem-pretty-sad-for-a-girl-so", "the cure"),
            ("olivia-dean-the-art-of-loving", "Man I Need"),
            ("kpop-demon-hunters-cast-huntr-x-saja-boys-kpop-d", "Golden"),
            ("taylor-swift-the-life-of-a-showgirl", "The Fate of Ophelia"),
            ("olivia-rodrigo-you-seem-pretty-sad-for-a-girl-so", "stupid song"),
            ("rose-new-trick", "new trick"),
            ("olivia-rodrigo-chappell-roan-expectations", "expectations"),
            ("sabrina-carpenter-short-n-sweet", "Espresso"),
            ("bad-bunny-debi-tirar-mas-fotos", "DtMF"),
            ("billie-eilish-hit-me-hard-and-soft", "BIRDS OF A FEATHER"),
            ("ariana-grande-petal", "petal"),
            ("sombr-i-barely-know-her", "back to friends"),
            ("harry-styles-kiss-all-the-time-disco-occasionall", "Aperture"),
            ("chappell-roan-the-rise-and-fall-of-a-midwest-pri", "Pink Pony Club"),
            ("taylor-swift-the-life-of-a-showgirl", "Opalite"),
            ("steve-lacy-oh-yeah", "Oh yeah?"),
            ("karol-g-no-me-arrepiento-de-sentir-tanto", "BbY WOW"),
        ] : [
            ("ella-langley-dandelion", "Choosin' Texas"),
            ("zach-bryan-young-manhood-and-other-donatable-org", "Lies"),
            ("adela-prima", "Nicole Kidman"),
            ("morgan-wallen-im-the-problem", "I'm The Problem"),
            ("jhene-aiko-westside-whimsy", "So Good"),
            ("sienna-spiro-visitor", "Great Expectation"),
            ("tame-impala-dracula", "Dracula"),
            ("sza-sos", "Snooze"),
            ("noah-kahan-the-great-divide", "The Great Divide"),
            ("dominic-fike-how-to-quit-smoking", "HOW TO QUIT SMOKING"),
            ("kendrick-lamar-gnx", "luther"),
            ("the-weeknd-hurry-up-tomorrow", "Timeless"),
            ("djo-the-crux", "Basic Being Basic"),
            ("benson-boone-american-heart", "Mystical Magical"),
            ("remi-wolf-mud", "Mud"),
            ("don-toliver-octane", "OCTANE"),
        ]
        var out: [Track] = []
        for (key, title) in picks {
            if let t = track(c, key, title), !out.contains(t) { out.append(t) }
        }
        // Fill up from each album's opener so a short list still makes full shelves.
        for album in c.albums where out.count < 16 {
            if let t = c.albumTracks[album.providerID]?.first, !out.contains(t) { out.append(t) }
        }
        return out
    }

    static func newest(_ c: MockCatalog) -> [Album] {
        c.albums.sorted { ($0.extra["released"] ?? "") > ($1.extra["released"] ?? "") }
    }

    static func home(_ c: MockCatalog) -> [Shelf] {
        let p = c.provider.short
        let chart = chart(c)
        let mixes = c.playlists.filter { !$0.isEditable }
        let mine = c.playlists.filter(\.isEditable)
        if c.provider == .youtubeMusic {
            let listenAgain = ["taylor-swift-the-life-of-a-showgirl", "olivia-dean-the-art-of-loving", "sabrina-carpenter-short-n-sweet",
                               "harry-styles-kiss-all-the-time-disco-occasionall", "billie-eilish-hit-me-hard-and-soft", "bad-bunny-debi-tirar-mas-fotos"]
                .compactMap { album(c, $0) }
            return [
                Shelf(id: "\(p)-quick", title: "Quick picks", style: .trackList, items: chart.prefix(12).map(MediaItem.track), moreToken: "quick"),
                Shelf(id: "\(p)-listen", title: "Listen again", style: .carousel,
                      items: listenAgain.map(MediaItem.album) + mixes.prefix(2).map(MediaItem.playlist) + mine.prefix(1).map(MediaItem.playlist), moreToken: "listen"),
                Shelf(id: "\(p)-mixes", title: "Your mixes", subtitle: "Made from your listening", style: .hero, items: mixes.dropFirst().map(MediaItem.playlist)),
                Shelf(id: "\(p)-top", title: "Top songs", subtitle: "United States", style: .trackList, items: chart.reversed().prefix(12).map(MediaItem.track), moreToken: "charts"),
                Shelf(id: "\(p)-artists", title: "Artists you listen to", style: .artists, items: c.artists.prefix(12).map(MediaItem.artist)),
            ]
        }
        return [
            Shelf(id: "\(p)-made", title: "Made For You", subtitle: "Mixes updated daily", style: .hero, items: mixes.map(MediaItem.playlist)),
            Shelf(id: "\(p)-new", title: "New releases for you", style: .carousel, items: newest(c).prefix(10).map(MediaItem.album), moreToken: "new"),
            Shelf(id: "\(p)-jump", title: "Jump back in", style: .carousel, items: c.albums.suffix(8).map(MediaItem.album) + mine.map(MediaItem.playlist), moreToken: "jump"),
            Shelf(id: "\(p)-top", title: "Your top songs this month", style: .trackList, items: chart.prefix(12).map(MediaItem.track)),
            Shelf(id: "\(p)-artists", title: "Your top artists", style: .artists, items: c.artists.prefix(12).map(MediaItem.artist)),
        ]
    }

    /// Signed out: the charts, what's new and moods, like YouTube Music's home before sign-in.
    static func anonymousHome(_ c: MockCatalog, moods: [MediaItem]) -> [Shelf] {
        let p = c.provider.short
        let albums = newest(c).filter { $0.kind == .album }
        return [
            Shelf(id: "\(p)-top", title: "Top songs", subtitle: "United States", style: .trackList, items: chart(c).prefix(12).map(MediaItem.track), moreToken: "charts"),
            Shelf(id: "\(p)-new", title: "New releases", style: .carousel, items: albums.prefix(14).map(MediaItem.album), moreToken: "new"),
            Shelf(id: "\(p)-moods", title: "Moods & genres", style: .carousel, items: moods, moreToken: "moods"),
            Shelf(id: "\(p)-trending", title: "Trending artists", style: .artists, items: c.artists.reversed().map(MediaItem.artist)),
        ]
    }

    static func explore(_ c: MockCatalog, moods: [MediaItem]) -> [Shelf] {
        let p = c.provider.short
        return [
            Shelf(id: "\(p)-new", title: c.provider == .spotify ? "Popular new releases" : "New releases", style: .carousel,
                  items: newest(c).filter { $0.kind == .album }.prefix(14).map(MediaItem.album), moreToken: "new"),
            Shelf(id: "\(p)-charts", title: c.provider == .spotify ? "Top 50 · USA" : "Top songs", style: .trackList, items: chart(c).map(MediaItem.track), moreToken: "charts"),
            Shelf(id: "\(p)-moods", title: "Moods & genres", style: .carousel, items: moods, moreToken: "moods"),
            Shelf(id: "\(p)-singles", title: "New singles & EPs", style: .carousel, items: newest(c).filter { $0.kind != .album }.map(MediaItem.album)),
            Shelf(id: "\(p)-trending", title: "Trending artists", style: .artists, items: c.artists.reversed().map(MediaItem.artist)),
        ]
    }

    /// The song both apps show playing: "the cure" from Olivia Rodrigo's new album, 1:12 in.
    static func nowPlaying(_ c: MockCatalog) -> DemoNowPlaying? {
        guard let album = album(c, "olivia-rodrigo-you-seem-pretty-sad-for-a-girl-so"), let tracks = c.albumTracks[album.providerID],
              let index = tracks.firstIndex(where: { $0.title == "the cure" }) else { return nil }
        return DemoNowPlaying(album: album, tracks: tracks, index: index, position: 72)
    }
}

extension MockProvider {
    /// The demo's now-playing pick, when this provider serves the demo dataset and has it.
    public var demoNowPlaying: DemoNowPlaying? { catalog.dataset == .demo ? DemoShelves.nowPlaying(catalog) : nil }

    /// A demo album by its key (see DemoCatalogData.swift), for screenshot runs.
    public func demoAlbum(_ key: String) -> Album? { catalog.dataset == .demo ? DemoShelves.album(catalog, key) : nil }

    /// A demo song by album key and title.
    public func demoTrack(_ albumKey: String, _ title: String) -> Track? { catalog.dataset == .demo ? DemoShelves.track(catalog, albumKey, title) : nil }
}
#endif
